 \label{prop:transportationDuality}
For any fixed $x \in \Delta^{p}$ and $z \in \Delta^d$,
\begin{align} \label{eqn:suppress_i}
    \min_{\alpha} \left( \sum_{j=1}^{p}\alpha_{j}x_{j} + \sum_{k=1}^dz_k\cdot\max_{j=1}^p(w^k_{j} - \alpha_{j}) \right) = \mathsf{Transport}(x,z;w^1,\ldots,w^d).
\end{align}

Therefore, when $D$ is a product of simplices, the constraints \eqref{eqn:max_sharp_set_dual-1} can be replaced in \eqref{eqn:max_sharp_set_dual} with the single inequality
\begin{align} \label{eqn:unsupress_i}

y\le\sum_{i=1}^{\tau}\mathsf{Transport}((x_{i,j})_{j=1}^{p_i},z;(w^1_{i,j})_{j=1}^{p_i},\ldots,(w^d_{i,j})_{j=1}^{p_i})+\sum_{k=1}^db^kz_k.

\end{align}

\begin{align} \label{eqn:suppress_i}
