\end{align}

\begin{align} \label{eqn:unsupress_i}

y\le\sum_{i=1}^{\tau}\mathsf{Transport}((x_{i,j})_{j=1}^{p_i},z;(w^1_{i,j})_{j=1}^{p_i},\ldots,(w^d_{i,j})_{j=1}^{p_i})+\sum_{k=1}^db^kz_k.

\end{align}

By using a variable $\gamma_{k}$ to model the value of $\max_{j=1}^{p}(w^k_{j} - \alpha_{j})$ for each $k\in\llbracket d\rrbracket$, the minimization problem on the LHS of~\eqref{eqn:suppress_i} is equivalent to
\begin{alignat*}{2}
\min_{\alpha,\gamma}\Set{\sum_{j=1}^{p}\alpha_{j}x_{j}+\sum_{k=1}^d\gamma_{k}z_k \;|\;
\gamma_{k} \ge w^k_{j}-\alpha_{j} \quad\forall k\in\llbracket d\rrbracket,j\in\llbracket p\rrbracket}
\end{alignat*}
which is a minimization LP with free variables $\alpha_j$ and $\gamma_k$.
Applying LP duality, this completes the proof of equation~\eqref{eqn:suppress_i}. The inequality
\eqref{eqn:unsupress_i} then arises by substituting equation~\eqref{eqn:suppress_i} into~\eqref{eqn:sharp_dual_prod_simpl}, for every simplex $i=1,\ldots,\tau$.
\qed

